package com.bank.merge;

import java.util.*;
import java.util.logging.*;

public class MergeMapDemo {
    private static final Logger log = Logger.getLogger("Merge");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Map<String, Integer> branchA = Map.of("Loan", 10, "Card", 5);
        Map<String, Integer> branchB = Map.of("Card", 3, "Locker", 7);
        MergeMapService service = new MergeMapService();

        log.info(() -> "merge() approach: " + service.mergeWithMerge(branchA, branchB));
        log.info(() -> "stream approach : " + service.mergeWithStream(branchA, branchB));
    }
}

// ─── Would be in service/MergeMapService.java ───
class MergeMapService {
    // Approach 1: Map.merge over a copy
    Map<String, Integer> mergeWithMerge(Map<String, Integer> a, Map<String, Integer> b) {
        Map<String, Integer> result = new HashMap<>(a);           // copy first
        b.forEach((k, v) -> result.merge(k, v, Integer::sum));     // sum on clash
        return result;
    }

    // Approach 2: stream concat + toMap with summing merge
    Map<String, Integer> mergeWithStream(Map<String, Integer> a, Map<String, Integer> b) {
        return java.util.stream.Stream.concat(
                a.entrySet().stream(), b.entrySet().stream())
            .collect(java.util.stream.Collectors.toMap(
                Map.Entry::getKey, Map.Entry::getValue, Integer::sum)); // sum duplicates
    }
}
